def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    bg_counts = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            bg_counts[val] = bg_counts.get(val, 0) + 1
    bg = max(bg_counts, key=bg_counts.get)

    # Move each non-background element based on its color
    moves = []
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != bg:
                dr, dc = 0, 0
                # Color-specific movement patterns
                if v == 0:
                    dr, dc = 1, 0    # down
                elif v == 1:
                    dr, dc = 1, -1   # down-left
                elif v == 5:
                    dr, dc = -1, -1  # up-left
                elif v == 6:
                    dr, dc = 1, -1   # down-left
                elif v == 7:
                    dr, dc = 1, 1    # down-right
                elif v == 8:
                    dr, dc = -1, 0   # up
                elif v == 9:
                    dr, dc = 0, 1    # right
                elif v == 2:
                    pass              # stays
                elif v == 3:
                    pass              # stays
                elif v == 4:
                    pass              # stays

                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    moves.append((nr, nc, v))

    out = [[bg] * cols for _ in range(rows)]
    for r, c, v in sorted(moves, key=lambda x: -x[0]):
        out[r][c] = v
    return out
